'use strict';
const passModel=globalThis.ABBATE_PASS;
const passStore='abbate-pass-demo-v1';
const passOwner='demo-a';
const passContent=document.querySelector('#pass-content');
const safe=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=value=>new Intl.DateTimeFormat('de-DE',{dateStyle:'medium'}).format(new Date(value+'T12:00:00'));
let shares=[];
try { const saved=JSON.parse(localStorage.getItem(passStore)||'[]'); if(Array.isArray(saved)) shares=saved; } catch {}
function persistShares(){localStorage.setItem(passStore,JSON.stringify(shares));}
function recordCard(record, verifier=false){return `<article class="pass-record"><div class="pass-record-top"><span>${safe(record.kind)}</span><span class="pass-state ${record.state==='revoked'?'revoked':''}">${record.state==='revoked'?'Widerrufen':'Bestätigter Beispielabschluss'}</span></div><h3>${safe(record.title)}</h3><dl><div><dt>Abgeschlossen am</dt><dd>${day(record.completedAt)}</dd></div>${!verifier&&record.reminderDue?`<div><dt>Nächster geplanter Termin</dt><dd>${day(record.reminderDue)}</dd></div>`:''}<div><dt>Ausgestellt von</dt><dd>${safe(record.issuer)}</dd></div><div><dt>Referenz</dt><dd>${safe(record.reference)}</dd></div></dl></article>`;}
function privateView(){return `<div class="pass-heading"><span>Dein persönlicher Verlauf</span><h1>Deine Schulungen.<br>Alles an einem Ort.</h1><p>Beispielteilnehmer A · In der fertigen App nur nach Anmeldung sichtbar.</p></div><div class="pass-summary"><div><small>Letzter Schulungsabschluss</small><strong>${day('2026-10-15')}</strong></div><div><small>Bestätigte Beispielabschlüsse</small><strong>${passModel.candidates(passOwner).length}</strong></div><a class="primary" href="#share">Nachweis per QR-Code freigeben</a></div><section class="pass-records" aria-label="Schulungsverlauf">${passModel.ownRecords(passOwner).map(r=>recordCard(r)).join('')}</section><p class="pass-note">Übungsergebnisse aus der Lern-App werden nicht zu Schulungsnachweisen. Ein echter Abschluss wird von der Fahrschule bestätigt.</p>`;}
function shareView(){const own=shares.filter(s=>s.ownerId===passOwner);return `<div class="pass-heading"><span>Du entscheidest, was sichtbar ist</span><h1>Einen Nachweis<br>gezielt freigeben.</h1><p>Wähle einzelne bestätigte Abschlüsse. Arbeitgeber oder Prüfer sehen nur diese Auswahl – ohne E-Mail-Adresse, Noten oder Übungsverlauf.</p></div><form id="share-form" class="pass-form"><fieldset><legend>Welche Abschlüsse möchtest du zeigen?</legend>${passModel.candidates(passOwner).map(r=>`<label class="pass-choice"><input type="checkbox" name="completion" value="${safe(r.id)}"><span><strong>${safe(r.title)}</strong><small>${day(r.completedAt)} · ${safe(r.kind)}</small></span></label>`).join('')}</fieldset><p>Die Freigabe läuft nach 24 Stunden ab und kann vorher widerrufen werden.</p><button class="primary" type="submit">Demo-Freigabe erstellen</button><p id="share-error" role="alert"></p></form><div id="new-share"></div><section class="pass-share-list"><h2>Deine Demo-Freigaben</h2>${own.length?own.map(s=>{const active=!s.revokedAt&&Date.parse(s.expiresAt)>Date.now();return `<article><div><strong>${s.completionIds.length} ausgewählte Abschlüsse</strong><p>${s.revokedAt?'Widerrufen':active?'Aktiv bis '+new Date(s.expiresAt).toLocaleString('de-DE'):'Abgelaufen'}</p></div>${active?`<div><button class="secondary" data-show="${safe(s.token)}">QR-Code zeigen</button><button class="secondary" data-revoke="${safe(s.token)}">Widerrufen</button></div>`:''}</article>`;}).join(''):'<p>Noch keine Freigabe erstellt.</p>'}</section><p class="pass-note">Diese lokale Vorschau kann Freigaben nur in diesem Browser auflösen. Auf einem zweiten Gerät erscheint deshalb noch kein Nachweis. Geräteübergreifende Prüfung und Widerruf erfolgen später über die zentrale Datenbank.</p>`;}
function verifyView(token){const proof=passModel.resolveShare(shares,token);return `<div class="pass-heading"><span>Nachweis prüfen · Ablaufvorschau</span><h1>${proof?'Freigegebene Abschlüsse.':'Kein Nachweis verfügbar.'}</h1><p>${proof?'Beispielteilnehmer A · ausschließlich freigegebene Angaben.':'Die Demo-Freigabe fehlt in diesem Browser, ist abgelaufen oder wurde widerrufen.'}</p></div>${proof?`<div class="pass-preview"><strong>Nur Beispieldaten – nicht als Nachweis verwenden</strong><span>In der fertigen Version wird der aktuelle Status online geprüft.</span></div><section class="pass-records">${proof.records.map(r=>recordCard(r,true)).join('')}</section>`:'<a class="secondary" href="#private">Zur persönlichen Vorschau</a>'}`;}
function renderPass(){const route=location.hash.slice(1);passContent.innerHTML=route.startsWith('verify/')?verifyView(route.slice(7)):route==='share'?shareView():privateView();document.querySelectorAll('.pass-tabs a').forEach(a=>a.setAttribute('aria-current',a.hash==='#'+(route||'private')?'page':'false'));}
async function showShare(token){const target=document.querySelector('#new-share');if(!target)return;target.innerHTML='<section class="pass-qr-panel"><div><h2>Dein Demo-QR-Code</h2><p>Kein echter Schulungsnachweis. Der Link funktioniert derzeit nur in diesem Browser.</p><a class="text-link" id="verify-link">Prüfansicht öffnen</a></div><canvas id="pass-qr" aria-label="QR-Code zur Demo-Freigabe"></canvas><button class="secondary" id="download-qr">QR-Code als PNG speichern</button></section>';const url=new URL(location.href);url.hash='verify/'+token;const link=document.querySelector('#verify-link');link.href=url.href;try{await AbbateQR.toCanvas(document.querySelector('#pass-qr'),url.href,{width:260,margin:4,errorCorrectionLevel:'M'});document.querySelector('#download-qr').onclick=()=>{const a=document.createElement('a');a.download='abbate-demo-nachweis.png';a.href=document.querySelector('#pass-qr').toDataURL('image/png');a.click();};}catch{target.textContent='Der QR-Code konnte nicht erstellt werden.';}target.scrollIntoView({behavior:'smooth',block:'center'});}
document.addEventListener('submit',event=>{if(event.target.id!=='share-form')return;event.preventDefault();try{const ids=new FormData(event.target).getAll('completion');passModel.selection(passOwner,ids);const bytes=crypto.getRandomValues(new Uint8Array(32)),token=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');shares.push({ownerId:passOwner,token,completionIds:ids,expiresAt:new Date(Date.now()+86400000).toISOString(),revokedAt:null});persistShares();renderPass();showShare(token);}catch(error){document.querySelector('#share-error').textContent=error.message;}});
document.addEventListener('click',event=>{const revoke=event.target.closest('[data-revoke]'),show=event.target.closest('[data-show]');if(revoke){const share=shares.find(s=>s.token===revoke.dataset.revoke&&s.ownerId===passOwner);if(share){share.revokedAt=new Date().toISOString();persistShares();renderPass();}}else if(show)showShare(show.dataset.show);});
addEventListener('hashchange',()=>{renderPass();window.scrollTo(0,0);});
renderPass();
